INSERT INTO library_sections (key, category, subcategory, name, description, keywords, tree, sort_order)
VALUES (
  'team-story',
  'about',
  'story',
  '{"ar":"قصتنا","en":"Our story"}'::jsonb,
  '{"ar":"جملة افتتاحية كبيرة، وصورة جنب فقرتين وتوقيع المؤسس.","en":"A big opening line, then a photo beside two paragraphs and the founder''s signature."}'::jsonb,
  ARRAY['about', 'story', 'founder', 'من نحن', 'قصتنا', 'حكايتنا']::text[],
  '{"breakpointStyles":{"mobile":{"paddingBottom":40,"paddingTop":40}},"children":[{"children":[{"breakpointStyles":{"mobile":{"marginBottom":24}},"children":[{"children":[{"children":[],"props":{"label":"النقطة","translations":{"en":{"label":"Dot"}}},"style":{"background":"accent","minHeight":8,"radius":999,"width":"8px"},"type":"div"},{"children":[],"props":{"role":"eyebrow","text":"قصتنا","translations":{"en":{"text":"Our story"}}},"style":{"color":"muted","fontSize":"sm","fontWeight":"semibold"},"type":"text"}],"props":{"label":"التسمية","translations":{"en":{"label":"Label"}}},"style":{"gap":8,"wrap":false},"type":"hFlex"},{"children":[],"props":{"level":"h2","role":"title","text":"بدأنا من أوضة في الدقي بعشر سماعات وموبايل واحد.","translations":{"en":{"text":"We started in a Dokki bedroom with ten earbuds and one phone."}}},"style":{"fontSize":"display-lg","letterSpacing":"tight","lineHeight":"tight","maxWidth":"20ch"},"type":"heading"}],"props":{"label":"العنوان","role":"intro","translations":{"en":{"label":"Heading"}}},"style":{"gap":12,"marginBottom":40},"type":"vFlex"},{"breakpointStyles":{"mobile":{"columns":1,"gap":24},"tablet":{"gap":32}},"children":[{"breakpointStyles":{"mobile":{"aspectRatio":"landscape"}},"children":[],"props":{"alt":"صورة من المتجر","role":"image","src":"stock:photo:0","translations":{"en":{"alt":"A photo from the store"}}},"style":{"aspectRatio":"portrait","objectFit":"cover","radius":24,"width":"100%"},"type":"image"},{"children":[{"breakpointStyles":{"mobile":{"fontSize":"md"}},"children":[],"props":{"role":"body","text":"كنا بنبيع لأصحابنا على واتساب، وكل طلب كنا بنوصله بنفسنا. النهارده بقينا فريق من ١٢ شخص وبنوصل لكل محافظات مصر.","translations":{"en":{"text":"We sold to friends on WhatsApp and delivered every order ourselves. Today we are a team of 12 delivering to every governorate."}}},"style":{"color":"foreground","fontSize":"lg","lineHeight":"relaxed"},"type":"paragraph"},{"breakpointStyles":{"mobile":{"fontSize":"md"}},"children":[],"props":{"role":"body","text":"لسه بنختار كل منتج بإيدينا، ولسه بنرد على كل رسالة.","translations":{"en":{"text":"We still pick every product by hand, and we still answer every message."}}},"style":{"color":"foreground","fontSize":"lg","lineHeight":"relaxed"},"type":"paragraph"},{"children":[],"props":{"role":"signature","text":"— منى، المؤسسة","translations":{"en":{"text":"— Mona, founder"}}},"style":{"color":"muted","fontFamily":"heading","fontWeight":"semibold"},"type":"text"}],"props":{"label":"النص","translations":{"en":{"label":"Text"}}},"style":{"gap":16},"type":"vFlex"}],"props":{"label":"التخطيط","translations":{"en":{"label":"Layout"}}},"style":{"alignItems":"end","columns":2,"gap":56},"type":"grid"}],"props":{"label":"الحاوية","translations":{"en":{"label":"Container"}}},"type":"container"}],"props":{"label":"قصتنا","translations":{"en":{"label":"Our story"}}},"style":{"paddingBottom":64,"paddingTop":64},"type":"section"}'::jsonb,
